  return(0);
 } </code></pre>The output of this program is ________ . (answer in integer) <br>Note: Assume that the program compiles and runs successfully.

Consider the recursive functions represented by the following code segment: <pre><code>int bar(int n) {
  if (n == 1) return 0;
  else return 1 + bar(n/2);
 }
 int foo(int n) {
  if (n == 1) return 1;
  else return 1 + foo(bar(n));
 } </code></pre>The smallest positive integer n for which [latex]\text{foo(n)}[/latex] returns [latex]5[/latex] is ________. (answer in integer) <br>Note: Ignore syntax errors (if any) in the function.

Consider the following program in C:<pre><code> #include &lt;stdio.h&gt;
 void func(int i, int j) {
  if(i < j) {
  	int i = 0;
  	while (i < 10) {
  		j += 2;
  		i++;
  	}
  }
  printf("%d", i);
 }
 int main() {
  	int i = 9, j = 10;
  	func(i, j);
  	return 0;
 }</code></pre> The output of the program is ________. (answer in integer)<br> Note: Assume that the program compiles and runs successfully.

Consider the following C program:
<pre><code>
#include &lt;stdio.h&gt;

int g(int n) {
    return (n+10);
}

int f(int n) {
    return g(n*2);
}

int main() {
    int sum, n;
    sum=0;
    for (n=1; n<3; n++)
        sum += g(f(n));
    printf ("%d", sum);
    return 0;
}
</code></pre>
The output of the given C program is ________. (Answer in integer)
